{
  "sections": [
    {
      "key": "verdict",
      "title": "निर्णय",
      "text": "तुमचा दुग्ध प्रकल्प आर्थिकदृष्ट्या शक्य आहे. डिएससीआर {{min_dscr}} आहे, जे चांगले आहे, आणि परतफेडीचा कालावधी {{payback_months}} महिने आहे."
    },
    {
      "key": "market",
      "title": "बाजार स्थिती",
      "text": "या गावात अंदाजे {{households}} घरं आहेत, ज्यामुळे दुग्ध उत्पादनासाठी स्थिर मागणी मिळते. बाजारातील अंतर कमी आहे आणि जवळपास कोणतेही स्पर्धक नाहीत. तुम्ही सहकारी संग्रह केंद्र, थेट घरांपर्यंत वितरण आणि मिठाई दुकानांद्वारे विक्री करू शकता."
    },
    {
      "key": "pricing",
      "title": "किंमत व नफा",
      "text": "एकूण प्रकल्प खर्च {{project_cost}} रुपये आहे, ज्यात बफेलो {{cost.animals}} आणि शेड {{cost.shed}} यांचा समावेश आहे. सरकारची सबसिडी {{subsidy}} रुपये मिळाल्यामुळे प्रारंभिक गुंतवणूक कमी होते. पहिल्या महिन्यातच ब्रेक‑इव्हन {{break_even_month}} महिन्यात साध्य होईल, आणि नफा चांगला दिसत आहे."
    },
    {
      "key": "risks",
      "title": "जोखीमे",
      "text": "मुख्य जोखीमे म्हणजे बफेलोंची आजारपण, कच्चा दूधाची किंमत बदलणे, आणि कर्जाची वेळेवर परतफेड. सबसिडी मिळण्याच्या प्रक्रियेत विलंब होऊ शकतो, ज्यामुळे रोख प्रवाहावर परिणाम होऊ शकतो."
    },
    {
      "key": "path_to_yes",
      "title": "यशाचा मार्ग",
      "text": "अभिनंदन! तुमचा प्रकल्प आधीच सर्व निकष पूर्ण करतो, म्हणून कोणतेही अतिरिक्त बदल आवश्यक नाहीत."
    },
    {
      "key": "next_steps",
      "title": "पुढील पावले",
      "text": "1. PMEGP कर्ज {{loan}} रुपये मंजूर करा. 2. सबसिडी {{subsidy}} रुपये मिळविण्यासाठी अर्ज करा. 3. बफेलो खरेदी करा आणि शेड बांधा. 4. दूध गोळा करणे व विक्रीचे नेटवर्क तयार करा. 5. नफा‑नुकसान व कर्ज परतफेडीचा रेकॉर्ड ठेवा."
    }
  ],
  "swot": {
    "strengths": [
      "सरकारी सबसिडी {{subsidy}} रुपये मिळणार",
      "स्पर्धा कमी असल्याने बाजारात जागा मिळते",
      "स्थानीय मागणी {{households}} घरांमधून स्थिर आहे"
    ],
    "weaknesses": [
      "प्रारंभिक खर्च {{project_cost}} जास्त आहे",
      "कर्जाची परतफेडीची जबाबदारी"
    ],
    "opportunities": [
      "दुग्ध उत्पादन वाढवून नवीन ग्राहक मिळवता येतील",
      "स्थानिक मिठाई दुकानांशी भागीदारी करून विक्री वाढवता येईल"
    ],
    "threats": [
      "बफेलोंची आजारपणाची शक्यता",
      "दुग्धाची बाजार किंमत बदलणे"
    ]
  }
}
